-- Rebuild Medina Book 3 lesson 13 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 52-54.
-- Nine Qur'anic strings hidden by DOC control characters were transcribed literally from visible PDF pages 52-53.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13';
  if old_rule_count <> 4 then raise exception 'Expected 4 generated Book 3 lesson 13 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '13', 'جَوَازِمُ الْمُضَارِعِ: الْجَازِمُ فِعْلًا وَاحِدًا (частицы, ставящие один глагол в джазм)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَحْرُفُ الَّتِي تَجْزِمُ فِعْلًا مُضَارِعًا وَاحِدًا أَرْبَعَةٌ: <span class="ar-tone-particle">لَمْ، وَلَمَّا، وَلَا النَّاهِيَةُ، وَلَامُ الْأَمْرِ</span>.</span><p class="rule-study-text">Шарх перечисляет четыре частицы, каждая из которых ставит один глагол настоящего-будущего времени в джазм.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре управляющие частицы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَرْفُ</span><span class="rule-table-ru">частица</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْنَاهُ</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَمْ</span><span class="rule-table-ru">не; отрицание прошедшего действия</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَفْيٍ وَجَزْمٍ</span><span class="rule-table-ru">частица отрицания и джазма</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمْ أَذْهَبْ.</span><span class="rule-table-ru">Я не пошёл.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَمَّا</span><span class="rule-table-ru">ещё не</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَفْيٍ وَجَزْمٍ</span><span class="rule-table-ru">частица отрицания и джазма</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَمَّا أَذْهَبْ.</span><span class="rule-table-ru">Я ещё не пошёл.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا النَّاهِيَةُ</span><span class="rule-table-ru">запретительная «не»</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَهْيٍ وَجَزْمٍ</span><span class="rule-table-ru">частица запрета и джазма</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا تَذْهَبْ.</span><span class="rule-table-ru">Не уходи.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَامُ الْأَمْرِ</span><span class="rule-table-ru">лям приказа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ أَمْرٍ وَجَزْمٍ</span><span class="rule-table-ru">частица приказа и джазма</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لِيَجْلِسْ كُلُّ طَالِبٍ فِي مَكَانِهِ.</span><span class="rule-table-ru">Пусть каждый студент сядет на своё место.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴾</span><span class="rule-example-ru">«Он не родил и не был рождён».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَلَمَّا يَدْخُلِ الْإِيمَانُ فِي قُلُوبِكُمْ ﴾</span><span class="rule-example-ru">«И вера ещё не вошла в ваши сердца».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا ﴾</span><span class="rule-example-ru">«Не печалься, ведь Аллах с нами».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">К кому обращается запретительная لَا</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">يَكْثُرُ دُخُولُ لَا النَّاهِيَةِ عَلَى الْمُخَاطَبِ وَالْغَائِبِ، وَلَا تَدْخُلُ عَلَى الْمُتَكَلِّمِ.</span><p class="rule-study-text">Она часто употребляется при обращении к собеседнику и в отношении отсутствующего лица, но не употребляется с формой говорящего.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры запрета</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُخَاطَبُ أَوِ الْغَائِبُ</span><span class="rule-table-ru">к кому относится</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُخَاطَبُ</span><span class="rule-table-ru">собеседник</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا تَذْهَبْ.</span><span class="rule-table-ru">Не уходи.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْغَائِبُ</span><span class="rule-table-ru">отсутствующее лицо</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا يَرْفَعْ أَحَدٌ صَوْتَهُ.</span><span class="rule-table-ru">Пусть никто не повышает голос.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ لَا يَسْخَرْ قَوْمٌ مِنْ قَوْمٍ ﴾</span><span class="rule-example-ru">«Пусть одни люди не насмехаются над другими».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">С кем употребляется لَامُ الْأَمْرِ</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">يَكْثُرُ دُخُولُ لَامِ الْأَمْرِ عَلَى الْغَائِبِ، وَقَدْ تَدْخُلُ عَلَى الْمُتَكَلِّمِ، وَلَا تَدْخُلُ عَلَى الْمُخَاطَبِ؛ لِأَنَّ لَهُ صِيغَةَ الْأَمْرِ: اِذْهَبْ.</span><p class="rule-study-text">Лям приказа чаще относится к отсутствующему лицу, иногда — к говорящему. С формой собеседника он не употребляется, поскольку для неё существует собственный императив.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Формы ляма приказа</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السِّيَاقُ</span><span class="rule-table-ru">позиция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صُورَةُ اللَّامِ</span><span class="rule-table-ru">форма ляма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فِي الِابْتِدَاءِ</span><span class="rule-table-ru">без предшествующего союза</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لِـ</span><span class="rule-table-ru">лям с касрой</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لِيَجْلِسْ كُلُّ طَالِبٍ فِي مَكَانِهِ.</span><span class="rule-table-ru">Пусть каждый студент сядет на своё место.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بَعْدَ الْوَاوِ</span><span class="rule-table-ru">после вау</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">وَلْـ</span><span class="rule-table-ru">лям с сукуном</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَلْنَحْمِلْ خَطَايَاكُمْ.</span><span class="rule-table-ru">И мы понесём ваши грехи.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بَعْدَ الْفَاءِ</span><span class="rule-table-ru">после фа</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">فَلْـ</span><span class="rule-table-ru">лям с сукуном</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَلْيَقْرَأْ كُلُّ طَالِبٍ الدَّرْسَ.</span><span class="rule-table-ru">Пусть каждый студент прочитает урок.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بَعْدَ ثُمَّ</span><span class="rule-table-ru">после «затем»</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">ثُمَّ لْـ</span><span class="rule-table-ru">лям с сукуном</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ثُمَّ لْيَكْتُبْهُ.</span><span class="rule-table-ru">Затем пусть он запишет его.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ لِيُنْفِقْ ذُو سَعَةٍ مِنْ سَعَتِهِ ﴾</span><span class="rule-example-ru">«Пусть обладающий достатком расходует из своего достатка».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ وَلْنَحْمِلْ خَطَايَاكُمْ ﴾</span><span class="rule-example-ru">«И мы понесём ваши грехи».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي ﴾</span><span class="rule-example-ru">«Пусть же они отвечают Мне и веруют в Меня».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-particle" dir="rtl" lang="ar">﴿ ثُمَّ لْيَقْضُوا تَفَثَهُمْ ﴾</span><span class="rule-example-ru">«Затем пусть они устранят свою неопрятность».</span></div></div></div>', 1, 'rule', 'Четыре частицы ставят один глагол настоящего-будущего времени в джазм: отрицательные «не» и «ещё не», запретительная частица и лям приказа.', 'الْأَحْرُفُ الَّتِي تَجْزِمُ فِعْلًا مُضَارِعًا وَاحِدًا أَرْبَعَةٌ: لَمْ، وَلَمَّا، وَلَا النَّاهِيَةُ، وَلَامُ الْأَمْرِ.'),
    ('Мединский курс (Том 3)', '13', 'الْجَزْمُ بِالطَّلَبِ (джазм в ответе на побуждение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">يُجْزَمُ <span class="ar-tone-verb">الْفِعْلُ الْمُضَارِعُ</span> إِذَا وَقَعَ جَوَابًا لِلطَّلَبِ، وَمِنْ أَنْوَاعِ الطَّلَبِ <span class="ar-tone-structure">الْأَمْرُ وَالنَّهْيُ</span>.</span><p class="rule-study-text">Глагол в ответе на приказ или запрет обозначает ожидаемое следствие побуждения и ставится в джазм.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الطَّلَبِ</span><span class="rule-table-ru">вид побуждения</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الطَّلَبُ</span><span class="rule-table-ru">побуждение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَوَابُ الطَّلَبِ</span><span class="rule-table-ru">ответ-следствие</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">приказ</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِجْتَهِدْ</span><span class="rule-table-ru">усердствуй</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">تَنْجَحْ</span><span class="rule-table-ru">преуспеешь</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِجْتَهِدْ تَنْجَحْ.</span><span class="rule-table-ru">Усердствуй — и преуспеешь.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّهْيُ</span><span class="rule-table-ru">запрет</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا تُهْمِلْ</span><span class="rule-table-ru">не будь небрежен</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">تَنْجَحْ</span><span class="rule-table-ru">преуспеешь</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا تُهْمِلْ تَنْجَحْ.</span><span class="rule-table-ru">Не будь небрежен — и преуспеешь.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّهْيُ</span><span class="rule-table-ru">запрет</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا تُشْرِكْ بِاللَّهِ</span><span class="rule-table-ru">не приобщай к Аллаху сотоварищей</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">تَدْخُلِ الْجَنَّةَ</span><span class="rule-table-ru">войдёшь в Рай</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا تُشْرِكْ بِاللَّهِ تَدْخُلِ الْجَنَّةَ.</span><span class="rule-table-ru">Не приобщай к Аллаху сотоварищей — войдёшь в Рай.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-card"><span class="rule-example-ar rule-quran-ar ar-tone-verb" dir="rtl" lang="ar">﴿ اُدْعُونِي أَسْتَجِبْ لَكُمْ ﴾</span><span class="rule-example-ru">«Взывайте ко Мне — Я отвечу вам».</span></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب: لَا تُهْمِلْ تَنْجَحْ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">арабский разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">полный перевод разбора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا</span><span class="rule-table-ru">не</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَهْيٍ وَجَزْمٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица запрета и джазма, построенная на сукуне и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ</span><span class="rule-table-ru">не является членом предложения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تُهْمِلْ</span><span class="rule-table-ru">ты пренебрегаешь</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَجْزُومٌ بِلَا النَّاهِيَةِ، وَعَلَامَةُ جَزْمِهِ السُّكُونُ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ أَنْتَ.</span><span class="rule-table-ru">глагол настоящего-будущего времени в джазме под управлением запретительной частицы; признак джазма — сукун; исполнитель — скрытое местоимение «ты»</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْفَاعِلُ: أَنْتَ</span><span class="rule-table-ru">исполнитель действия — «ты»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَنْجَحْ</span><span class="rule-table-ru">ты преуспеешь</span></td><td><span class="rule-table-ar ar-tone-jazm" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَجْزُومٌ بِالطَّلَبِ، وَعَلَامَةُ جَزْمِهِ السُّكُونُ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ أَنْتَ.</span><span class="rule-table-ru">глагол настоящего-будущего времени в джазме как ответ на побуждение; признак джазма — сукун; исполнитель — скрытое местоимение «ты»</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْفَاعِلُ: أَنْتَ</span><span class="rule-table-ru">исполнитель действия — «ты»</span></td></tr></tbody></table></div></div></div>', 2, 'rule', 'Глагол настоящего-будущего времени ставится в джазм, когда является ответом-следствием приказа или запрета.', 'يُجْزَمُ الْفِعْلُ الْمُضَارِعُ إِذَا وَقَعَ جَوَابًا لِلطَّلَبِ، وَمِنْ أَنْوَاعِ الطَّلَبِ الْأَمْرُ وَالنَّهْيُ.'),
    ('Мединский курс (Том 3)', '13', 'النُّدْبَةُ (зов скорби или боли)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">النُّدْبَةُ</span> نِدَاءُ الْمُتَفَجَّعِ عَلَيْهِ أَوِ الْمُتَوَجَّعِ مِنْهُ، وَحَرْفُهَا <span class="ar-tone-particle">وَا</span>.</span><p class="rule-study-text">Это особый зов скорби по кому-либо либо восклицание человека, испытывающего боль.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два значения нудбы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">все примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُتَفَجَّعُ عَلَيْهِ</span><span class="rule-table-ru">тот или то, о чём скорбят</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَامُعْتَصِمَاهْ. وَإِسْلَامَاهْ.</span><span class="rule-table-ru">О Мутасим! О Ислам!</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُتَوَجَّعُ مِنْهُ</span><span class="rule-table-ru">то, что причиняет боль</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَارَأْسَاهْ. وَابَطْنَاهْ.</span><span class="rule-table-ru">О моя голова! О мой живот!</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب: وَارَأْسَاهْ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُزْءُ</span><span class="rule-table-ru">часть формы</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">арабский разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">полный перевод разбора</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">وَا</span><span class="rule-table-ru">частица зова</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نِدَاءٍ وَنُدْبَةٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица обращения и нудбы, построенная на сукуне и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ</span><span class="rule-table-ru">не является членом предложения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">رَأْسَاهْ</span><span class="rule-table-ru">моя голова</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُنَادًى مَنْدُوبٌ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الْمُقَدَّرَةُ عَلَى مَا قَبْلَ يَاءِ الْمُتَكَلِّمِ الْمَحْذُوفَةِ، وَهُوَ مُضَافٌ، وَيَاءُ الْمُتَكَلِّمِ الْمَحْذُوفَةُ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.</span><span class="rule-table-ru">оплакиваемое обращение в винительном падеже; фатха подразумевается перед удалённой йа первого лица; слово является первым членом идафы, а удалённая йа первого лица находится в синтаксическом месте родительного падежа как второй член идафы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ: رَأْسِي</span><span class="rule-table-ru">исходная форма — «моя голова»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَلِفُ</span><span class="rule-table-ru">алиф перед конечной ха</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ نُدْبَةٍ زَائِدٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">добавочная буква нудбы, построенная на сукуне и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ نُدْبَةٍ زَائِدٌ</span><span class="rule-table-ru">добавочная буква нудбы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْهَاءُ</span><span class="rule-table-ru">конечная ха</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ سَكْتٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">буква паузы, построенная на сукуне и не имеющая синтаксического места</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَرْفُ سَكْتٍ</span><span class="rule-table-ru">буква паузы</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Исходная и преобразованная формы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ</span><span class="rule-table-ru">исходная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِيغَةُ النُّدْبَةِ</span><span class="rule-table-ru">форма нудбы</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا حَدَثَ</span><span class="rule-table-ru">что изменилось</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَارَأْسِي</span><span class="rule-table-ru">о моя голова</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَارَأْسَاهْ</span><span class="rule-table-ru">восклицание боли: «О моя голова!»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حُذِفَتْ يَاءُ الْمُتَكَلِّمِ، وَزِيدَتْ أَلِفُ النُّدْبَةِ وَهَاءُ السَّكْتِ.</span><span class="rule-table-ru">йа первого лица удалена; добавлены алиф нудбы и ха паузы</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'Нудба — обращение скорбящего к тому, о ком он скорбит, либо восклицание из-за боли; её специальная частица — «ва».', 'النُّدْبَةُ نِدَاءُ الْمُتَفَجَّعِ عَلَيْهِ أَوِ الْمُتَوَجَّعِ مِنْهُ، وَحَرْفُ النُّدْبَةِ وََا.'),
    ('Мединский курс (Том 3)', '13', 'آهِ (имя глагола настоящего времени «мне больно»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">آهِ</span> ٱسْمُ فِعْلٍ مُضَارِعٍ بِمَعْنَى <span class="ar-tone-verb">أَتَوَجَّعُ</span>، مَبْنِيٌّ عَلَى الْكَسْرِ، وَفَاعِلُهُ ضَمِيرٌ مُسْتَتِرٌ وُجُوبًا تَقْدِيرُهُ <span class="ar-tone-subject">أَنَا</span>.</span><p class="rule-study-text">Это имя глагола настоящего времени со значением «я испытываю боль»; оно построено на касре, а его обязательный скрытый исполнитель — местоимение «я».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Различие двух форм</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّنْوِينُ</span><span class="rule-table-ru">танвин</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَتَى تُقَالُ</span><span class="rule-table-ru">когда произносится</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">آهِ</span><span class="rule-table-ru">ах</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بِلَا تَنْوِينٍ</span><span class="rule-table-ru">без танвина</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا تَوَجَّعْتَ وَتَأَلَّمْتَ مِنْ مَرَضٍ مُعَيَّنٍ</span><span class="rule-table-ru">когда боль вызвана определённой болезнью</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَتَوَجَّعُ مِنْ شَيْءٍ مُعَيَّنٍ.</span><span class="rule-table-ru">Мне больно из-за определённой причины.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">آهٍ</span><span class="rule-table-ru">ах</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بِالتَّنْوِينِ</span><span class="rule-table-ru">с танвином</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِذَا تَوَجَّعْتَ وَتَأَلَّمْتَ مِنْ كُلِّ شَيْءٍ</span><span class="rule-table-ru">когда боль выражается неопределённо, от всего</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَتَوَجَّعُ مِنْ كُلِّ شَيْءٍ.</span><span class="rule-table-ru">Мне больно от всего.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Название танвина</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">يُسَمَّى التَّنْوِينُ فِي <span class="ar-tone-verb">آهٍ</span> تَنْوِينَ تَنْكِيرٍ.</span><p class="rule-study-text">Этот танвин называется танвином неопределённости.</p></div></div>', 4, 'rule', 'Форма «ах» является именем глагола со значением «я испытываю боль»; отсутствие или наличие танвина различает конкретный и неопределённо-общий источник боли.', 'آهِ ٱسْمُ فِعْلٍ مُضَارِعٍ بِمَعْنَى أَتَوَجَّعُ، مَبْنِيٌّ عَلَى الْكَسْرِ، وَفَاعِلُهُ ضَمِيرٌ مُسْتَتِرٌ وُجُوبًا تَقْدِيرُهُ أَنَا. وَآهِ بِلَا تَنْوِينٍ لِلتَّوَجُّعِ مِنْ شَيْءٍ مُعَيَّنٍ، وَآهٍ بِالتَّنْوِينِ لِلتَّوَجُّعِ مِنْ كُلِّ شَيْءٍ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'جَوَازِمُ الْمُضَارِعِ
الْجَازِمُ فِعْلاً وَاحِداً
الأحرفُ التي تَجْزِمُ فعلاً واحداً أربعةٌ ، هي :
1- لَمْ ، وهي حرف نفي ، نحو : لم أذهبْ . قال تعالى : ﴿ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴾ .
2- لَمَّا ، وهي حرف نفي ، نحو : لَمَّا أذهبْ .
قال تعالى : ﴿ وَلَمَّا يَدْخُلِ الْإِيمَانُ فِي قُلُوبِكُمْ ﴾ .
3- لاَ النَّاهِيَةُ ، وهي حرف نَهْي ، نحو : لا تَذْهَبْ .
قال تعالى : ﴿ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا ﴾ .
* يَكْثُرُ دخول لا النَّاهية على الْمُخَاطَب ،كما في المثالين السابقين ، وعلى الغائب ، نحو : لا يَرْفعْ أحدٌ صَوْتَه . قال تعالى: ﴿ لَا يَسْخَرْ قَوْمٌ مِنْ قَوْمٍ ﴾ .
ولا تدخل على الْمُتكلَّم .
4- لاَمُ الأَمْرِ ، وهي حرف أَمْر، نحو : لِيَجْلِسْ كُلُّ طالبٍ في مكانه . قال تعالى :
﴿ لِيُنْفِقْ ذُو سَعَةٍ مِنْ سَعَتِهِ ﴾ .
* يكثر دخول لام الأمر على الغائب ، كما في المثالين السَّابقين، وقد تدخل على المتكلَّم،
نحو قوله تعالى : ﴿ وَلْنَحْمِلْ خَطَايَاكُمْ ﴾ ونحو قولك : لِنَجْلِسْ معاً .
ولا تدخل على المخاطَب ؛ لأنه له صِيغَة تَخُصُّه هي : الأَمر ( اذهبْ ) .
* لام الأمر مكسورة ، كما في الأمثلة ، وتكون سَاكنة بعد ( الواو ، والفاء ، وثُمَّ )
قال تعالى: ﴿ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي ﴾ وقال تعالى: ﴿ ثُمَّ لْيَقْضُوا تَفَثَهُمْ ﴾ ونحو قولك : فَلْيَقْرَأْ كلُّ طالبٍ الدرسَ ثُمَّ لْيَكْتُبْه .', 52, 53, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', '* من جوازم الفعل الواحد : الجزمُ بالطَّلبِ ، أي أَنْ يَقَعَ المضارعُ جواباً للطَّلَب . والطَّلَب يكون بأمورٍ كثيرةٍ ، منها : الأَمْرُ ، والنَّهْيُ .
مثالُ الأمرِ  : اجتهدْ تَنجحْ . قال تعالى : ﴿ اُدْعُونِي أَسْتَجِبْ لَكُمْ ﴾ .
مثالُ النَّهيِّ : لا تُهْمِلْ تنجحْ   . لا تُشرِكْ باللهِ تَدْخُلِ الجنَّةَ .
الإعراب :  لا تهملْ تنجحْ .
لا : حرف نَهْيٍ وَجزْمٍ مبني على السكون لا محلّ له من الإعراب .
تهملْ : فعل مضارع مجزوم بـ ( لا ) النَّاهية وعلامة جزمه السُّكون ، والفاعل
ضمير مستتر تقديره ( أنت ) .
تنجحْ : فعل مضارع مجزوم بالطَّلَب وعلامة جزمه السكون ، والفاعل ضمير مستتر
تقديره ( أنت ) .', 53, 53, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13' and sort_order = 2;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'النُّدْبَةُ
النُّدْبَةُ ، هي : نِدَاءُ الْمُتَفَجَّعِ عليه ، أو الْمُتَوَجَّعِ مِنْه .
حرف النُّدْبَةِ : وَا .
مثال المتفجَّع عليه : وَامُعْتَصِمَاهْ . وَإِسْلاَمَاهْ .
مثال المتوجَّع مِنه  : وارَأْسَاهْ . وَابَطْنَاهْ .
الإعراب :  وَارَأْسَاهْ .
وا : حرف نِداء ونُدبة مبني على السكون لا محلّ له من الإعراب .
رأساه : منادى مندوب منصوب وعلامة نصبه الفتحة المقدّرة على ما قبل ياء
المتكلَّم المحذوفة، وهو مضاف وياء المتكلَّم المحذوفة في محل جر مضاف إليه.
والألف : حرف ندبة زائد مبني على السكون لا محلّ له من الإعراب .
والهاء   : حرف سَكْت مبني على السكون لا محلّ له من الإعراب .
* وارأساه ، أصله : وَارَأْسِي .', 54, 54, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13' and sort_order = 3;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'آهِ
آهِ : اسمُ فعلٍ مضارعٍ بمعنى ( أَتَوَجَّعُ ) مبنيٌّ على الكسر ، وفاعله ضمير مستتر وجوباً ، تقديره ( أنا ) .
* تقول ( آهِ ) بدون تنوين : إذا تَوَجَّعْتَ وتَأَلَّمْتَ مِنْ مَرَضٍ مُعَيَّن .
وتقول ( آهٍ ) بالتنوين : إذا توجَّعت وتألَّمت مِن كُل شيء ؛ ولذلك يُسَمَّى هذا التَّنوين : تنوين تَنْكِير .', 54, 54, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13' and sort_order = 4;

  select count(*) into new_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '13';
  select count(*) into source_count from public.rule_sources rs join public.rules r on r.id = rs.rule_id where r.course_name = 'Мединский курс (Том 3)' and r.lesson_number = '13';
  if new_rule_count <> 4 or source_count <> 4 then raise exception 'Book 3 lesson 13 verification failed: rules %, sources %', new_rule_count, source_count; end if;
end
